using System;
using System.Linq;
using System.Collections.Generic;
namespace LegendsCompanion {
public static class TravelGuide {
 static Dictionary<string,List<string>> edges=new Dictionary<string,List<string>>();
 static Dictionary<string,string> dru=new Dictionary<string,string>(),wiz=new Dictionary<string,string>();
 public const string Sources="Ports: https://eqlwiki.com/Rituals\nRoutes: adjacent-zone lists on the linked zone pages. Reviewed 2026-09-11. Fewest documented zone transitions; walking distance, danger and access can change the best choice.";
 static TravelGuide(){
  Add("South Kaladim","North Kaladim");Add("Felwithe","Southern Felwithe");Add("Nektulos Forest","Neriak Foreign Quarter");Add("Neriak Foreign Quarter","Neriak Commons");Add("Neriak Commons","Neriak Third Gate");
  Add("West Karana","Qeynos Hills|North Karana");Add("North Karana","East Karana|South Karana");Add("East Karana","Highpass Hold|Gorge of King Xorbb");Add("South Karana","Lake Rathetear|Splitpaw Lair");
  Add("Greater Faydark","Felwithe|Butcherblock Mountains|Lesser Faydark|Crushbone");Add("Lesser Faydark","Steamfont Mountains|Mistmoore Castle");Add("Butcherblock Mountains","South Kaladim|Dagnor's Cauldron");Add("Steamfont Mountains","Ak'Anon");Add("Dagnor's Cauldron","Estate of Unrest|Kedge Keep");
  Add("Lavastorm Mountains","Temple of Solusek Ro|Solusek's Eye|Nagafen's Lair|Najena|Nektulos Forest");Add("Toxxulia Forest","Kerra Island|Erudin|Paineel");Add("Paineel","The Hole|Warrens");Add("The Feerrott","Rathe Mountains|Oggok|Cazic-Thule|Plane of Fear|Innothule Swamp");Add("Misty Thicket","Rivervale|Runnyeye");Add("Gorge of King Xorbb","Runnyeye");Add("Rathe Mountains","Lake Rathetear");Add("Lake Rathetear","Arena");Add("Qeynos Hills","North Qeynos|Blackburrow|Surefall Glade");Add("West Commonlands","East Commonlands|Kithicor Forest|Befallen");
  Add("North Qeynos","South Qeynos|Qeynos Aqueducts");Add("Erudin","Erudin Palace");Add("Innothule Swamp","Grobb|Upper Guk|South Ro");Add("North Ro","East Freeport|East Commonlands|Oasis of Marr|New Sebilis Expedition");Add("South Ro","Oasis of Marr");Add("Kithicor Forest","Rivervale|Highpass Hold");Add("Everfrost Peaks","Halas|Blackburrow|Permafrost Caverns");Add("East Commonlands","Nektulos Forest|West Freeport");
  Port(dru,"Butcherblock Mountains","Circle of Butcherblock");Port(dru,"The Feerrott","Circle of Feerrott");Port(dru,"Lavastorm Mountains","Circle of Lavastorm");Port(dru,"Misty Thicket","Circle of Misty Thicket");Port(dru,"North Karana","Circle of North Karana");Port(dru,"South Ro","Circle of South Ro");Port(dru,"Steamfont Mountains","Circle of Steamfont");Port(dru,"Stonebrunt Mountains","Circle of Stonebrunt");Port(dru,"Surefall Glade","Circle of Surefall Glade");Port(dru,"Toxxulia Forest","Circle of Toxxulia");Port(dru,"West Commonlands","Circle of West Commons");
  Port(wiz,"Cazic-Thule","Cazic Temple Portal");Port(wiz,"Greater Faydark","Greater Faydark Portal");Port(wiz,"Nektulos Forest","Nektulos Portal");Port(wiz,"North Karana","North Karana Portal");Port(wiz,"North Ro","North Ro Portal");Port(wiz,"Stonebrunt Mountains","Stonebrunt Portal");Port(wiz,"Toxxulia Forest","Toxxulia Portal");Port(wiz,"West Commonlands","West Commons Portal");Port(wiz,"West Karana","West Karana Portal");Port(wiz,"Plane of Hate","Alter Plane: Hate");Port(wiz,"Plane of Sky","Alter Plane: Sky");
