 static void Port(Dictionary<string,string> d,string z,string spell){d[z]=spell;}
 static void Add(string a,string b){foreach(var z in b.Split('|')){if(!edges.ContainsKey(a))edges[a]=new List<string>();if(!edges.ContainsKey(z))edges[z]=new List<string>();edges[a].Add(z);edges[z].Add(a);}}
 static List<string> Path(string from,string to){var q=new Queue<List<string>>();q.Enqueue(new List<string>{from});var seen=new HashSet<string>{from};while(q.Count>0){var p=q.Dequeue();var last=p.Last();if(last==to)return p;if(!edges.ContainsKey(last))continue;foreach(var n in edges[last])if(seen.Add(n))q.Enqueue(p.Concat(new[]{n}).ToList());}return null;}
 static string ForClass(string zone,Dictionary<string,string> ports){var paths=ports.Select(p=>new{Spell=p.Value,Path=Path(p.Key,zone)}).Where(p=>p.Path!=null).OrderBy(p=>p.Path.Count).ThenBy(p=>p.Spell).ToList();if(paths.Count==0)return "Route not yet verified";var best=paths[0];return best.Spell+" — "+String.Join(" → ",best.Path);}
 public static string ForZone(string zone){zone=Guides.Zone(zone);if(zone=="Plane of Sky")return "Druid: East Commons portal → East Freeport → click the orb → Plane of Sky\nWizard: West Commons Portal → East Commons → East Freeport → click the orb → Plane of Sky\nDruid arrival and East Freeport orb location reported by user in Legends (2026-09-11).";string s="Druid: "+ForClass(zone,dru)+"\nWizard: "+ForClass(zone,wiz);if(zone=="Plane of Hate")s+="\nWizard reagent: Fuligan Soulstone of Innoruuk; arrange planar access.";if(zone=="Plane of Sky")s+="\nWizard reagent: Cloudy Stone of Veeshan; arrange planar access.";if(zone=="The Hole"||zone=="Plane of Fear"||zone=="Kedge Keep")s+="\nCheck dungeon/planar entry requirements before travel.";return s;}
 public static string ForFarm(Farm f){return !String.IsNullOrWhiteSpace(f.PortRoute)?f.PortRoute:String.Join("\n",(f.Zone??"").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(z=>ForZone(z.Trim())));}
 public static bool HasRoute(string zone){return !ForZone(zone).Contains("Route not yet verified");}
}
